export const roleClaimKeys = [
  'role',
  'roles',
  'http://schemas.microsoft.com/ws/2008/06/identity/claims/role',
] as const

export const roles = {
  contestsAdmin: 'AdministradorConcursos',
  rolesAdmin: 'AdministradorRoles',
  user: 'Usuario',
} as const

export type JwtPayload = Record<string, unknown>
export type Identity = {
  userId?: string
  name?: string
  email?: string
  roles: string[]
}

const readString = (payload: JwtPayload, keys: string[]) => {
  for (const key of keys) {
    const value = payload[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return undefined
}

export function decodeJwtPayload(token?: string | null): JwtPayload | undefined {
  if (!token || token.split('.').length !== 3) return undefined

  try {
    const encodedPayload = token.split('.')[1]
    const base64 = encodedPayload.replace(/-/g, '+').replace(/_/g, '/')
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=')
    const json = decodeURIComponent(
      Array.from(atob(padded))
        .map((character) => `%${character.charCodeAt(0).toString(16).padStart(2, '0')}`)
        .join(''),
    )
    const payload: unknown = JSON.parse(json)
    return payload && typeof payload === 'object' && !Array.isArray(payload)
      ? (payload as JwtPayload)
      : undefined
  } catch {
    return undefined
  }
}

export function normalizeRoles(payload?: JwtPayload): string[] {
  if (!payload) return []
  const values = roleClaimKeys.flatMap((key) => {
    const value = payload[key]
    return typeof value === 'string' ? [value] : Array.isArray(value) ? value : []
  })
  return [...new Set(values.filter((value): value is string => typeof value === 'string').map((value) => value.trim()).filter(Boolean))]
}

export function deriveIdentity(token?: string | null): Identity | undefined {
  const payload = decodeJwtPayload(token)
  if (!payload) return undefined
  return {
    userId: readString(payload, ['sub', 'nameid', 'id']),
    name: readString(payload, ['name', 'unique_name', 'given_name']),
    email: readString(payload, ['email', 'emailaddress']),
    roles: normalizeRoles(payload),
  }
}

export const hasRole = (identity: Identity | undefined, role: string) =>
  Boolean(identity?.roles.includes(role))
export const isContestsAdmin = (identity?: Identity) => hasRole(identity, roles.contestsAdmin)
export const isRolesAdmin = (identity?: Identity) => hasRole(identity, roles.rolesAdmin)
export const isAdministrator = (identity?: Identity) =>
  isContestsAdmin(identity) || isRolesAdmin(identity)
export const isUser = (identity?: Identity) => hasRole(identity, roles.user)

export function roleDescription(identity?: Identity): string {
  if (isContestsAdmin(identity)) return 'Administrador de concursos'
  if (isRolesAdmin(identity)) return 'Administrador de roles'
  if (isUser(identity)) return 'Estudiante'
  return 'Sin rol asignado'
}

import { deriveIdentity, isAdministrator, isUser } from './identity'

export const tokenStorageKey = 'token'
export const forbiddenRoute = '/forbidden'

export function getInitialRoute(token?: string | null): string {
  const identity = deriveIdentity(token)
  if (!identity) return '/login'
  if (isAdministrator(identity)) return '/admin/dashboard'
  // No student route exists in this workspace yet; avoid granting an invented path.
  if (isUser(identity)) return forbiddenRoute
  return forbiddenRoute
}

export function clearSession() {
  sessionStorage.removeItem(tokenStorageKey)
}

import type { ReactNode } from 'react'
import { Navigate } from 'react-router-dom'
import { deriveIdentity } from '@/lib/auth/identity'
import { forbiddenRoute } from '@/lib/auth/session'
import { routes } from './constants'

type Props = { children: ReactNode; allowedRoles: readonly string[] }

export function RoleRoute({ children, allowedRoles }: Props) {
  const token = sessionStorage.getItem('token')
  if (!token) return <Navigate to={routes.login} replace />

  const identity = deriveIdentity(token)
  if (!identity || !identity.roles.some((role) => allowedRoles.includes(role))) {
    return <Navigate to={forbiddenRoute} replace />
  }

  return <>{children}</>
}

import { LogOut, Menu, X } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Avatar, IconButton } from '@/components/common'
import type { Identity } from '@/lib/auth/identity'
import { roleDescription } from '@/lib/auth/identity'
import { clearSession } from '@/lib/auth/session'
import { cn } from '@/lib/utils/cn'

export function UserMenu({ identity }: { identity?: Identity }) {
  const [open, setOpen] = useState(false)
  const navigate = useNavigate()
  const buttonRef = useRef<HTMLButtonElement>(null)
  const name = identity?.name || identity?.email || 'Usuario'

  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setOpen(false)
        buttonRef.current?.focus()
      }
    }
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [])

  const logout = () => {
    clearSession()
    setOpen(false)
    navigate('/login', { replace: true })
  }

  return (
    <div className="relative">
      <button
        ref={buttonRef}
        type="button"
        aria-label="Abrir menú de usuario"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="flex cursor-pointer items-center gap-2 rounded-md p-1 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus)]"
      >
        <Avatar name={name} />
        <span className="hidden max-w-40 truncate text-sm font-semibold sm:block">{name}</span>
        <Menu className="size-4" aria-hidden="true" />
      </button>
      {open && (
        <div
          role="menu"
          aria-label="Menú de usuario"
          className="absolute right-0 z-30 mt-2 w-64 rounded-md border border-[var(--border)] bg-white p-3 shadow-[var(--shadow-md)]"
        >
          <div className="mb-3 border-b border-[var(--border)] pb-3">
            <p className="truncate font-semibold">{name}</p>
            {identity?.email && <p className="truncate text-sm text-[var(--text-secondary)]">{identity.email}</p>}
            <p className="text-sm text-[var(--text-secondary)]">{roleDescription(identity)}</p>
          </div>
          <button
            type="button"
            role="menuitem"
            onClick={logout}
            className="flex w-full cursor-pointer items-center gap-2 rounded-md px-2 py-2 text-left text-sm font-semibold text-[var(--danger)] hover:bg-[var(--surface-muted)] focus-visible:outline-2 focus-visible:outline-[var(--focus)]"
          >
            <LogOut className="size-4" aria-hidden="true" /> Cerrar sesión
          </button>
        </div>
      )}
    </div>
  )
}

export function MobileNavigationButton({ open, onClick }: { open: boolean; onClick: () => void }) {
  return (
    <IconButton label={open ? 'Cerrar navegación administrativa' : 'Abrir navegación administrativa'} onClick={onClick}>
      {open ? <X className="size-5" /> : <Menu className="size-5" />}
    </IconButton>
  )
}

import { LayoutDashboard, PlusCircle, Trophy } from 'lucide-react'
import { useMemo, useState } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import { BrandMark } from '@/components/common'
import type { Identity } from '@/lib/auth/identity'
import { isAdministrator, isContestsAdmin } from '@/lib/auth/identity'
import { cn } from '@/lib/utils/cn'
import { routes } from '@/routes/constants'

type NavigationItem = {
  label: string
  path: string
  icon: typeof Trophy
  visible: (identity?: Identity) => boolean
  keywords: string[]
}

export const adminNavigation: NavigationItem[] = [
  { label: 'Resumen', path: routes.dashboard, icon: LayoutDashboard, visible: isAdministrator, keywords: ['inicio', 'panel'] },
  { label: 'Concursos', path: routes.contests, icon: Trophy, visible: isContestsAdmin, keywords: ['competencias'] },
  { label: 'Crear concurso', path: routes.newContest, icon: PlusCircle, visible: isContestsAdmin, keywords: ['nuevo'] },
]

export function AdminSidebar({ identity, onNavigate }: { identity?: Identity; onNavigate?: () => void }) {
  const [query, setQuery] = useState('')
  const location = useLocation()
  const visibleItems = useMemo(() => {
    const normalizedQuery = query.trim().toLocaleLowerCase()
    return adminNavigation.filter((item) =>
      item.visible(identity) && (!normalizedQuery || [item.label, ...item.keywords].some((term) => term.toLocaleLowerCase().includes(normalizedQuery))),
    )
  }, [identity, query])

  return (
    <div className="flex h-full flex-col p-5">
      <BrandMark alt="UPDS Judge" />
      <p className="mt-3 font-semibold">Panel Administrativo</p>
      <label className="mt-8 text-sm font-semibold" htmlFor="admin-module-search">Buscar módulos</label>
      <input
        id="admin-module-search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="Buscar módulo..."
